const Koa = require('koa');
const Router = require('koa-router');
const bodyParser = require('koa-bodyparser');
const { exec } = require('child_process');

const app = new Koa();
const router = new Router();

router.post('/monitor/commands', async (ctx) => {
  const { filter_flags = '', command_regex } = ctx.request.body;

  if (!command_regex) {
    ctx.status = 400;
    ctx.body = {
      code: 400,
      message: 'command_regex is required',
    };
    return;
  }

  try {
    const command = `ps ${filter_flags}`;
    const processes = await new Promise((resolve, reject) => {
      exec(command, (error, stdout, stderr) => {
        if (error) {
          reject(stderr);
        } else {
          resolve(stdout);
        }
      });
    });

    const regex = new RegExp(command_regex);
    const processList = processes.split('\n').slice(1).filter(line => regex.test(line)).map(line => {
      const parts = line.trim().split(/\s+/);
      return {
        processId: parseInt(parts[1], 10),
        processString: line,
      };
    });

    ctx.status = 200;
    ctx.body = processList;
  } catch (error) {
    ctx.status = 500;
    ctx.body = {
      code: 500,
      message: 'Internal Server Error',
    };
  }
});

app
  .use(bodyParser())
  .use(router.routes())
  .use(router.allowedMethods());

app.listen(5000, '0.0.0.0', () => {
  console.log('Server running on http://0.0.0.0:5000');
});
</CODE>```
